import { createRequire } from "node:module";
import * as path from "node:path";
import type { IpcClientAsync, IpcClientSync } from "./types.js";
import { type HostCallTargets, synchronousHostCall } from "./wasm/host_call.js";
import { type WasmWorker, isWasmWorker } from "./wasm/backend.js";

/**
 * The surface of a Node-API addon generated by ipc-codegen's `--napi` over a service's FFI entry
 * (`<service>_napi.cpp`): bytes in, bytes out, on the calling thread or on the libuv pool. The
 * addon serializes calls itself, as the FFI entry requires.
 */
export interface NapiFfiAddon {
  /** The schema's service name the addon was generated for. */
  service: string;
  /** The process's one instance, on the calling thread. */
  call(input: Uint8Array): Uint8Array;
  /** The process's one instance, on the libuv thread pool. */
  callAsync(input: Uint8Array): Promise<Uint8Array>;
  /** A new instance (addons generated with instances): state of its own, called on the calling thread. */
  create?(): NapiInstance;
  callInstance?(
    instance: NapiInstance,
    input: Uint8Array,
    hostCall?: (target: string, request: Uint8Array) => Uint8Array,
  ): Uint8Array;
  destroy?(instance: NapiInstance): void;
}

/** An addon instance, opaque to JS. */
export type NapiInstance = { readonly __napiInstance: unique symbol };

/** Options for a napi backend over an addon generated with instances. */
export interface NapiInstanceOptions {
  /** The addon file. */
  addonPath: string;
  /**
   * Where the instance runs, for the asynchronous backend: a WasmWorker shared with the other
   * instances on it (wasm modules or napi instances), which can then be its host-call targets
   * synchronously; default a worker of its own.
   */
  worker?: WasmWorker;
  /** The services the instance reaches through its host (see HostCallTarget). */
  hostCall?: HostCallTargets;
  logger?: (msg: string) => void;
}

/**
 * Load a generated FFI addon from `addonPath`. Node caches native modules by path, so every load of
 * one file returns the same addon, and with it the same service state: the FFI entry has one
 * context per loaded library, not one per backend.
 */
export function loadNapiFfiAddon(
  addonPath: string,
  expectedService?: string,
): NapiFfiAddon {
  const require = createRequire(import.meta.url);
  const addon = require(path.resolve(addonPath)) as NapiFfiAddon;
  if (
    typeof addon?.call !== "function" ||
    typeof addon?.callAsync !== "function"
  ) {
    throw new Error(
      `${addonPath}: not an ipc-codegen FFI addon (no call/callAsync)`,
    );
  }
  if (expectedService !== undefined && addon.service !== expectedService) {
    throw new Error(
      `${addonPath}: addon serves '${addon.service}', expected '${expectedService}'`,
    );
  }
  return addon;
}

function asUint8Array(buffer: Uint8Array): Uint8Array {
  return new Uint8Array(buffer.buffer, buffer.byteOffset, buffer.byteLength);
}

/** Asynchronous backend over a generated FFI addon: each call runs on the libuv thread pool. */
export class NapiFfiBackend implements IpcClientAsync {
  private destroyed = false;

  constructor(private readonly addon: NapiFfiAddon) {}

  /**
   * An instance of its own on a worker, when the addon has instances: the backend then has state
   * of its own, and its calls run on that worker's thread, one at a time, as a wasm module's do.
   * `create` binds the platform's worker scripts.
   */
  static async instance(
    options: NapiInstanceOptions,
    createWorker: () => WasmWorker,
  ): Promise<NapiInstanceBackend> {
    const addon = loadNapiFfiAddon(options.addonPath);
    if (!addon.create) {
      throw new Error(
        `${options.addonPath}: the addon has no instances (regenerate it)`,
      );
    }
    const ownsWorker = !isWasmWorker(options.worker);
    const worker = options.worker ?? createWorker();
    try {
      const slot = await worker.load(
        { napi: path.resolve(options.addonPath) },
        options.hostCall,
        options.logger,
      );
      return new NapiInstanceBackend(worker, slot, ownsWorker);
    } catch (e) {
      if (ownsWorker) {
        await worker.destroy();
      }
      throw e;
    }
  }

  async call(input: Uint8Array): Promise<Uint8Array> {
    if (this.destroyed) {
      throw new Error(`${this.addon.service}: napi backend used after destroy()`);
    }
    return asUint8Array(await this.addon.callAsync(input));
  }

  /** The addon stays loaded (node cannot unload one); this only stops further calls. */
  destroy(): Promise<void> {
    this.destroyed = true;
    return Promise.resolve();
  }
}

/** An addon instance on a worker (NapiFfiBackend.instance). */
export class NapiInstanceBackend implements IpcClientAsync {
  /** @internal */
  constructor(
    private readonly worker: WasmWorker,
    private readonly slot: number,
    private readonly ownsWorker: boolean,
  ) {}

  /** @internal This instance's slot when it runs on `worker`, for host-call targets beside it. */
  slotOn(worker: WasmWorker): number | undefined {
    return this.worker === worker ? this.slot : undefined;
  }

  call(input: Uint8Array): Promise<Uint8Array> {
    return this.worker.call(this.slot, input);
  }

  unref(): void {
    if (this.ownsWorker) {
      this.worker.unref();
    }
  }

  async destroy(): Promise<void> {
    if (this.ownsWorker) {
      await this.worker.destroy();
    } else {
      await this.worker.unload(this.slot);
    }
  }
}

/** Synchronous backend over a generated FFI addon: each call runs on, and blocks, the calling thread. */
export class NapiFfiBackendSync implements IpcClientSync {
  private destroyed = false;

  constructor(private readonly addon: NapiFfiAddon) {}

  /**
   * An instance of its own on the calling thread, when the addon has instances. Its host calls are
   * answered on this thread, so they must answer synchronously.
   */
  static instance(
    options: Omit<NapiInstanceOptions, "worker" | "logger">,
  ): NapiInstanceBackendSync {
    const addon = loadNapiFfiAddon(options.addonPath);
    if (!addon.create) {
      throw new Error(
        `${options.addonPath}: the addon has no instances (regenerate it)`,
      );
    }
    const hostCall = synchronousHostCall(options.hostCall, (backend) => {
      const syncCaller = (backend as { syncCaller?: unknown }).syncCaller;
      return typeof syncCaller === "function"
        ? (syncCaller.call(backend) as (request: Uint8Array) => Uint8Array)
        : undefined;
    });
    return new NapiInstanceBackendSync(addon, addon.create(), hostCall);
  }

  call(input: Uint8Array): Uint8Array {
    if (this.destroyed) {
      throw new Error(`${this.addon.service}: napi backend used after destroy()`);
    }
    return asUint8Array(this.addon.call(input));
  }

  destroy(): void {
    this.destroyed = true;
  }
}

/** An addon instance on the calling thread (NapiFfiBackendSync.instance). */
export class NapiInstanceBackendSync implements IpcClientSync {
  private destroyed = false;

  /** @internal */
  constructor(
    private readonly addon: NapiFfiAddon,
    private readonly instance: NapiInstance,
    private readonly hostCall:
      | ((target: string, request: Uint8Array) => Uint8Array)
      | undefined,
  ) {}

  /** @internal A synchronous call into the instance, for a host-call target on this thread. */
  syncCaller(): (input: Uint8Array) => Uint8Array {
    return (input) => this.call(input);
  }

  call(input: Uint8Array): Uint8Array {
    if (this.destroyed) {
      throw new Error(`${this.addon.service}: napi backend used after destroy()`);
    }
    return asUint8Array(
      this.addon.callInstance!(this.instance, input, this.hostCall),
    );
  }

  destroy(): void {
    if (!this.destroyed) {
      this.destroyed = true;
      this.addon.destroy!(this.instance);
    }
  }
}
